#define WORLD_DIMENSIONS uvec2(1<<29, 1<<28)
#define BLUE_NOISE_DIM 512

uint inverse_lod = 0u;
int scale = 1;

float density(uvec2 cell, uint cell_size) {
    return 1.0f;
}

uint findMSB(uint c) {
    return uint(log2(float(c)));
}

uint imod(uint n, uint d) {
    return n - (n / d) * d;
}

uvec2 imod2(uvec2 n, uint d) {
    return n - (n / d) * d;
}

uvec2 uhash22(uvec2 src) {
    const uint M = 0x5bd1e995u;
    uvec2 h = uvec2(1190494759u, 2147483647u);
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

uint uhash12(uvec2 src) {
    const uint M = 0x5bd1e995u;
    uint h = 1190494759u;
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

// creates a vaguely hexagonal grid, jitters points and rejects samples based on density
// returns a ivec3 where (x,y) point to the generated sample and (z) stores the signed distance
ivec4 cell_offset(uvec2 coords, ivec2 offset, uint cell_size, uint r) {

    uvec2 cell = uvec2(ivec2(coords / cell_size) + offset);
    uvec2 cell_uv = imod2(coords, cell_size);

    // offset every other column by half a cell to create a vaguely hexagonal grid
    ivec2 cell_centre = ivec2(cell_size >> 1) + offset * int(cell_size);
    cell_centre.y -= int(cell.x & 1u) * int(cell_size >> 1);

    // jitter the sampled position by some random value while still respecting the hexagonal grids bounds
    vec2 jitter_scale = vec2(0.375f + 0.1333f, 0.375f);
    uvec2 wrapped_cell = cell & ((WORLD_DIMENSIONS >> findMSB(cell_size)) - 1u);
    ivec2 jitter = ivec2(vec2(imod2(uhash22(wrapped_cell), cell_size)) * jitter_scale);
    cell_centre -= jitter;

    // sample blue noise for the cell and reject its sample based on a density threshold
    vec2 read = vec2(cell & uint(BLUE_NOISE_DIM - 1)) / float(BLUE_NOISE_DIM);
    float noise = texture(iChannel0, read).r;
    float density_base = 0.0f;
    int cell_mask = 1;//int(1.0f - step(density(cell, cell_size) - density_base, noise));

    ivec2 delta = ivec2(cell_uv) - cell_centre;

    // try to round closer to the real value while respecting the grid's lod
    // be careful to round only just before blitting, not earlier
    // because you don't want the coordinate to be jittered into/out of a collision at a different LOD
    ivec2 round_carry = ivec2(0);//(cell_centre & int(scale - 1)) >> max(int(inverse_lod) - 1, 0);
    cell_centre = ((cell_centre >> inverse_lod) + round_carry) << inverse_lod;

    float d = -(length(vec2(cell_uv) - vec2(cell_centre)) - float(r)) * float(cell_mask) - (1.0f - float(cell_mask)) * float(cell_size);

    uint cell_hash = uhash12(wrapped_cell);

    return ivec4(delta * cell_mask - (1 - cell_mask) * int(cell_size), int(d), cell_hash);
}

ivec2 offsets[9] = ivec2[9](
    ivec2(-1, -1), ivec2(0, -1), ivec2(1, -1),
    ivec2(-1,  0), ivec2(0,  0), ivec2(1,  0),
    ivec2(-1,  1), ivec2(0,  1), ivec2(1,  1)
);

ivec4 closest_cell(uvec2 coords, uint cell_size, uint r) {

    ivec4 selected_cell;
    selected_cell.z = -1;

    for (uint i = 0u; i < 9u; i++) {
        ivec4 cell = cell_offset(coords, offsets[i], cell_size, r);
        if (cell.z >= selected_cell.z) {
            selected_cell = cell;
        }
    }

    return selected_cell;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    inverse_lod = uint(mod(iTime * 0.5f, 4.0f));
    scale = 1 << (inverse_lod);

    uint x = uint(fragCoord.x);
    uint z = uint(fragCoord.y);

    uvec2 coords = uvec2(x * uint(scale), z * uint(scale));

    uint ecotope_base_cell_size = 32u;
    uint ecotope_increment = 32u;
    uint ecotope_num_layers = 4u;
    uint ecotope = 0u;

    int selected_object = -1;
    ivec4 object_positions[3 * 9];

    for (uint i = 0u; i < ecotope_num_layers; i++) {
        uint cell_size = ecotope_base_cell_size + ecotope_increment * (ecotope_num_layers - i - 1u);
        ivec4 closest_object = closest_cell(coords, cell_size << 1u, cell_size >> 1u);

        for (uint j = i; j > 0u; j--) {
            uint check_cell_size = ecotope_base_cell_size + ecotope_increment * (ecotope_num_layers - j);
            ivec4 closest_collision = closest_cell(uvec2(ivec2(coords) - closest_object.xy), check_cell_size << 1u, (check_cell_size + cell_size) >> 1u);
            closest_object.z = closest_object.z * int(closest_collision.z <= 0) - int(closest_collision.z > 0);
        }

        object_positions[i] = closest_object;

        if (closest_object.z >= 0) {
            selected_object = int(i);
        }
    }

#define hue(v)  ( 1. - 1.5*(v) * vec4(.8,.6,1,0) )
    fragColor = hue(float((selected_object + 1)) / 5.0f);
}
